import { prisma } from "@/lib/prisma";
import IDCardClient from "./IDCardClient";

export default async function IDCardPage() {
  // 1. Ambil data pengurus yang AKTIF saja
  const rawMembers = await prisma.pengurus.findMany({
    where: { status: "AKTIF" },
    orderBy: { nama: "asc" },
  });

  // 2. Format datanya biar sesuai sama ID Card Client
  const formattedMembers = rawMembers.map((m) => ({
    id: m.id,
    name: m.nama,
    role: m.jabatan,
    class: m.kelas,
    nis: m.nis, // Penting buat QR Code
    image: m.fotoUrl || null, // Foto profil mereka
    email: m.email || "-",
    phone: m.hp || "-",
    frontDesign: m.idCardDesign || null
  }));

  return <IDCardClient initialMembers={formattedMembers} />;
}